// GOHIGHLEVEL — LEAD INTAKE AND ROUTING — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 intake and routing" and
// "02 follow-up sequence"). build.py regenerates both from this one file, and validate.py
// fails if they drift apart — so you never paste it between them by hand.
//
// A blank id or key means that step is SKIPPED, never that the run fails. That is what lets
// this be demonstrated on a screen-share before a single GoHighLevel credential exists.

// ---------------------------------------------------------------- The GoHighLevel sub-account
// Location id: the Location ID on Settings -> Business Profile, or the id in the URL when
// you are inside the sub-account.
const GHL_LOCATION_ID = '';

// GoHighLevel signs in through an n8n credential, never through a value in this node.
// Create a Header Auth credential: Name "Authorization", Value "Bearer <Private Integration
// token>" (Settings -> Private Integrations, scopes contacts.write / opportunities.write /
// conversations.write). Select it on every GoHighLevel node, then set this to true. Left
// false, the workflows build the exact request and stop in front of the write.
const GHL_CREDENTIAL_ADDED = false;
const GHL_API_BASE     = 'https://services.leadconnectorhq.com';
const GHL_API_VERSION  = '2021-07-28';

// ---------------------------------------------------------------- The pipeline
// The pipeline a lead is filed into, and the stages it can be filed at. The workflow
// decides WHICH stage a lead belongs in; the id is what makes that a real stage rather than
// a label. Pipeline id: Pipelines -> your pipeline -> the id in the URL.
const GHL_PIPELINE_ID = '';
const STAGES = [
  { stage: 'New lead',        id: '' },
  { stage: 'Quote requested', id: '' },
  { stage: 'Support',         id: '' }
];

// ---------------------------------------------------------------- Custom fields and tags
// Custom field name -> its GoHighLevel field id (Settings -> Custom Fields). The value is
// read off the lead by `from`. A blank id is skipped rather than written as an empty field,
// so a half-mapped account still writes a clean contact.
const CUSTOM_FIELDS = [
  { name: 'Lead source',  id: '', from: 'source'  },
  { name: 'Enquiry type', id: '', from: 'wants'   },
  { name: 'Summary',      id: '', from: 'summary' }
];

// On every contact this workflow writes. The routing rule adds its own.
const BASE_TAGS = ['automation-intake'];

// ---------------------------------------------------------------- Who gets what
// The rule table. First match wins. A rule may match on the intake source, on what the
// person wants, on both — and the last rule matches nothing on purpose, so a lead that fits
// no rule still lands somewhere rather than nowhere.
const OWNERS = [
  { owner: 'Ada',  user_id: '' },
  { owner: 'Ben',  user_id: '' },
  { owner: 'Cara', user_id: '' }
];
const ROUTING_RULES = [
  { match: { wants: 'support' },  owner: 'Cara', stage: 'Support',         tags: ['support'] },
  { match: { wants: 'quote' },    owner: 'Ben',  stage: 'Quote requested', tags: ['quote'] },
  { match: { wants: 'demo' },     owner: 'Ben',  stage: 'New lead',        tags: ['demo'] },
  { match: { source: 'phone' },   owner: 'Ben',  stage: 'New lead',        tags: ['phone'] },
  { match: { source: 'email' },   owner: 'Ada',  stage: 'New lead',        tags: ['email'] },
  { match: { source: 'website' }, owner: 'Ada',  stage: 'New lead',        tags: ['website'] },
  { match: {},                    owner: 'Ada',  stage: 'New lead',        tags: ['unrouted'] }
];

// ---------------------------------------------------------------- Follow-up sequence
// The ordered touches a lead receives if nobody has answered it. A lead gets touch 1 after
// `after_hours` with no movement, then touch 2, then touch 3 — and stops the moment anyone
// replies or the stage moves. The counter is `touches_sent` on the contact; the sequence is
// only ever advanced by one per run, so a lead cannot be double-touched.
const SEQUENCE = [
  { touch: 1, after_hours: 24, channel: 'email', label: 'check-in',
    subject: 'Quick check-in on your enquiry',
    line: 'Just making sure your message reached us and got a reply. Happy to pick this up whenever suits you.' },
  { touch: 2, after_hours: 72, channel: 'email', label: 'value nudge',
    subject: 'Something that might help',
    line: 'I have put a short summary together covering what you asked about. Want me to send it over?' },
  { touch: 3, after_hours: 120, channel: 'sms', label: 'last check-in',
    line: 'Last one from me — shall I close this off, or keep it open for later?' }
];

// The hard stop, enforced in code rather than implied. A lead at this many touches is never
// sent another, whatever the timings say.
const MAX_TOUCHES = 3;

// The stages a lead can still be sequenced in. A lead that has left them is finished, and
// the sequence stops rather than chasing a won or lost job.
const OPEN_STAGES = ['New lead', 'Quote requested', 'Support'];
const STOP_ON_STAGE_MOVE = true;

// Signed on the end of each email. Blank -> no signature line.
const FROM_NAME = '';

// Where the sequence's state lives on the contact. GoHighLevel's opportunities carry the stage,
// but not how many touches have gone out or when the last one was — those live in custom fields,
// and these are their ids (Settings -> Custom Fields). Point them at wherever you keep them and
// the read is complete; leave them blank and the counter reads 0, which is honest rather than
// invented.
const SEQ_TOUCHES_FIELD_ID    = '';
const SEQ_LAST_TOUCH_FIELD_ID = '';
const SEQ_LAST_REPLY_FIELD_ID = '';

// How many opportunities one read pulls. GoHighLevel caps a page at 100. If there are more than
// this, the run says so (see `more_pages` on the plan) rather than pretending it read them all.
const PIPELINE_PAGE_LIMIT = 100;

// ---------------------------------------------------------------- What counts as a lead
// A lead with no way to reach the person is not a lead. Whether a message is also required
// is a judgement call, so it is a setting rather than an assumption.
const REQUIRE_CONTACT = true;    // an email address or a phone number
const REQUIRE_MESSAGE = false;   // false: a named contact with no message is still filed

// ---------------------------------------------------------------- Safety switch
//   DRY_RUN true  (how it ships) -> nothing is written and nothing is sent. The payloads are
//                                   built in full and shown, so the first run after import
//                                   is always safe.
//   DRY_RUN false                -> the contact is created or updated and the touches send.
// Both also need GHL_LOCATION_ID and GHL_CREDENTIAL_ADDED above; without them the workflows stay
// in preview whatever this says.
const DRY_RUN = true;

const MODE = DRY_RUN !== true ? 'live' : 'preview';

// ---------------------------------------------------------------- The demo pipeline
// The leads "02 follow-up sequence" runs against until GoHighLevel is wired up. Every person
// here is invented. The mix is deliberate — it has to show every decision the sequence makes:
//   * 30 h quiet, 0 touches                    -> due touch 1
//   * one touch sent, 80 h quiet                -> due touch 2
//   * 5 h quiet, 0 touches                      -> not due yet
//   * replied 10 h ago                          -> STOP: they replied
//   * stage is 'Won'                            -> STOP: left the sequence
//   * three touches already sent                -> STOP: sequence finished
const DEMO_PIPELINE = [
  { contact_key: 'rachel@brightpath-dental.example', name: 'Rachel Okonkwo', company: 'Brightpath Dental',
    email: 'rachel@brightpath-dental.example', phone: '', contact_id: 'demo-1001', owner: 'Ben',
    stage: 'New lead', touches_sent: 0, last_touch_hours_ago: 30, last_reply_hours_ago: -1 },
  { contact_key: 'tom@beasleylogistics.example', name: 'Tom Beasley', company: 'Beasley Logistics',
    email: 'tom@beasleylogistics.example', phone: '', contact_id: 'demo-1002', owner: 'Cara',
    stage: 'Support', touches_sent: 1, last_touch_hours_ago: 80, last_reply_hours_ago: -1 },
  { contact_key: '07700900456', name: 'Ravi Menon', company: 'Menon & Co',
    email: '', phone: '07700 900456', contact_id: 'demo-1003', owner: 'Ben',
    stage: 'New lead', touches_sent: 0, last_touch_hours_ago: 5, last_reply_hours_ago: -1 },
  { contact_key: 'elena@example.com', name: 'Elena Rossi', company: '',
    email: 'elena@example.com', phone: '', contact_id: 'demo-1004', owner: 'Ada',
    stage: 'Quote requested', touches_sent: 1, last_touch_hours_ago: 100, last_reply_hours_ago: 10 },
  { contact_key: 'june@example.com', name: 'June Park', company: '',
    email: 'june@example.com', phone: '', contact_id: 'demo-1005', owner: 'Ada',
    stage: 'Won', touches_sent: 1, last_touch_hours_ago: 100, last_reply_hours_ago: -1 },
  { contact_key: 'dana@example.com', name: 'Dana Whitfield', company: '',
    email: 'dana@example.com', phone: '', contact_id: 'demo-1006', owner: 'Ada',
    stage: 'New lead', touches_sent: 3, last_touch_hours_ago: 200, last_reply_hours_ago: -1 }
];

const SETTINGS = {
  ghl_location_id: GHL_LOCATION_ID.trim(),
  ghl_credential_added: GHL_CREDENTIAL_ADDED === true,
  ghl_api_base:    GHL_API_BASE.trim().replace(/\/+$/, ''),
  ghl_api_version: GHL_API_VERSION.trim(),

  ghl_pipeline_id: GHL_PIPELINE_ID.trim(),
  stages:          STAGES,

  custom_fields: CUSTOM_FIELDS,
  base_tags:     BASE_TAGS,

  owners:        OWNERS,
  routing_rules: ROUTING_RULES,

  sequence:            SEQUENCE,
  max_touches:         Number(MAX_TOUCHES) || SEQUENCE.length,
  open_stages:         OPEN_STAGES,
  stop_on_stage_move:  STOP_ON_STAGE_MOVE === true,
  from_name:           FROM_NAME.trim(),
  demo_pipeline:       DEMO_PIPELINE,

  seq_touches_field_id:    SEQ_TOUCHES_FIELD_ID.trim(),
  seq_last_touch_field_id: SEQ_LAST_TOUCH_FIELD_ID.trim(),
  seq_last_reply_field_id: SEQ_LAST_REPLY_FIELD_ID.trim(),
  pipeline_page_limit:     Number(PIPELINE_PAGE_LIMIT) || 100,

  require_contact: REQUIRE_CONTACT === true,
  require_message: REQUIRE_MESSAGE === true,

  stage_on_arrival: 'New lead',

  // derived flags — the gates read these, never the raw constants
  mode:        MODE,
  dry_run:     MODE !== 'live',
  ghl_enabled: MODE === 'live'
    && GHL_LOCATION_ID.trim() !== ''
    && GHL_CREDENTIAL_ADDED === true
};

// config passes the incoming payload through untouched under `lead`, so whichever trigger
// fired the next node reads the payload from the same place. It runs once per incoming item.
const incoming = $input.all().length ? $input.all().map((i) => i.json || {}) : [{}];
return incoming.map((lead) => ({ json: Object.assign({}, SETTINGS, { lead: lead }) }));

// The pipeline "02 follow-up sequence" runs against until GoHighLevel is wired up: the demo
// leads from the config node, with their last-touch and last-reply times turned into real
// timestamps so "quiet for 30 hours" means something relative to now. Every person is
// invented, and the mix is chosen so every decision the sequence makes is visible in one run.
const cfg = $('config').first().json;
const now = Date.now();
const at = (h) => (h === null || h === undefined || Number(h) < 0)
  ? '' : new Date(now - Number(h) * 3600000).toISOString().slice(0, 16).replace('T', ' ');

return (cfg.demo_pipeline || []).map((r) => ({
  json: {
    contact_key:  r.contact_key,
    name:         r.name,
    company:      r.company || '',
    email:        r.email || '',
    phone:        r.phone || '',
    contact_id:   r.contact_id || '',
    owner:        r.owner || '',
    stage:        r.stage || '',
    touches_sent: Number(r.touches_sent) || 0,
    last_touch:   at(r.last_touch_hours_ago),
    last_reply:   at(r.last_reply_hours_ago),
    _demo:        true
  }
}));

// GoHighLevel is configured but the read failed. The run STOPS here rather than falling back to
// the demo pipeline — a fabricated lead must never be sequenced against a real account. This
// node's output carries the reason, so the failure is a visible step rather than a quiet morning.
return $input.all().map((i) => {
  const j = i.json || {};
  const err = j.error || j;
  const detail = (err && (err.message || err.description || err.error)) || j;
  return {
    json: {
      _outcome: 'read failed',
      _reason: 'could not read the pipeline from GoHighLevel — nothing was sequenced',
      ghl_response: typeof detail === 'string' ? detail : JSON.stringify(detail).slice(0, 600)
    }
  };
});

// Maps the pipeline into the ONE row shape the sequence decides on, whether it came from
// GoHighLevel or from the built-in demo pipeline. Everything downstream is identical either way.
//
// GoHighLevel's /opportunities/search returns opportunities, not the contact facts the sequence
// wants — how many touches have gone out, when the last one was. Those live in custom fields, so
// their ids are settings (`SEQ_*_FIELD_ID`); a blank id reads as 0 rather than being invented.
// The stage arrives as a pipelineStageId, which is turned back into the name `OPEN_STAGES` uses.
//
// If the account has more opportunities than one page, that is REPORTED (`more_pages`), never
// silently dropped.
const cfg = $('config').first().json;

const stageById = {};
for (const s of cfg.stages || []) if (s.id) stageById[s.id] = s.stage;

function fromOpportunity(o) {
  const cf = {};
  for (const f of (o.customFields || [])) cf[f.id] = f.value;
  const c = o.contact || {};
  return {
    contact_key:  c.email || c.phone || o.contactId || o.id || '',
    name:         c.name || c.contactName || o.name || '',
    company:      c.companyName || '',
    email:        c.email || '',
    phone:        c.phone || '',
    contact_id:   o.contactId || c.id || '',
    owner:        o.assignedTo || '',
    stage:        stageById[o.pipelineStageId] || o.pipelineStageName || 'unknown',
    touches_sent: Number(cf[cfg.seq_touches_field_id]) || 0,
    last_touch:   cfg.seq_last_touch_field_id ? (cf[cfg.seq_last_touch_field_id] || '') : '',
    last_reply:   cfg.seq_last_reply_field_id ? (cf[cfg.seq_last_reply_field_id] || '') : ''
  };
}

const rows = [];
let more = false;
let total = null;
let from = '';

for (const item of $input.all()) {
  const j = item.json || {};
  if (Array.isArray(j.opportunities)) {
    for (const o of j.opportunities) rows.push(fromOpportunity(o));
    const meta = j.meta || {};
    total = (meta.total === undefined || meta.total === null) ? null : Number(meta.total);
    more = !!(meta.nextPageUrl || meta.nextPage || meta.startAfterId);
    from = 'GoHighLevel';
  } else if (j.contact_key || j.email || j.contact_id || j.stage) {
    // The demo pipeline already emits the row shape.
    rows.push(j);
    if (!from) from = 'the demo pipeline';
  }
}

return [{
  json: {
    rows: rows,
    rows_read: rows.length,
    more_pages: more,
    total_available: total,
    _from: from || 'an empty pipeline'
  }
}];

// Decides, for every lead in the pipeline, whether it is DUE the next touch, WAITING for its
// time, or STOPPED — and for a stopped one, why. One item out, carrying all three lists, so a
// single run reads as a report rather than as N separate decisions.
//
// The stop checks run in order and a lead leaves at the first one that applies: leaving an
// open stage beats replying, and both beat the counter.
const cfg = $('config').first().json;
const source = $input.first().json || {};
const rows = source.rows || [];
const seq = cfg.sequence || [];
const open = cfg.open_stages || [];
const maxTouches = Number(cfg.max_touches) || seq.length;
const now = Date.now();

// A timestamp the way the pipeline wrote it, tolerating the shapes a CRM or a sheet hands
// back. An unreadable date is treated as absent, never as "now" — a lead we cannot date is
// not chased on a guess.
function ms(v) {
  const s = String(v || '').trim();
  if (!s) return null;
  let t = Date.parse(s);
  if (isNaN(t)) t = Date.parse(s.replace(' ', 'T'));
  if (isNaN(t)) t = Date.parse(s.replace(' ', 'T') + 'Z');
  return isNaN(t) ? null : t;
}

const due = [], waiting = [], stopped = [], board = {};

for (const r of rows) {
  board[r.stage] = (board[r.stage] || 0) + 1;

  const base = {
    contact_key: r.contact_key, name: r.name, company: r.company, owner: r.owner,
    stage: r.stage, email: r.email, phone: r.phone, contact_id: r.contact_id,
    touches_sent: Number(r.touches_sent) || 0
  };

  const lastTouch = ms(r.last_touch);
  const lastReply = ms(r.last_reply);

  if (cfg.stop_on_stage_move && open.indexOf(r.stage) < 0) {
    stopped.push(Object.assign({}, base, {
      reason: 'left the sequence — stage is ' + (r.stage || 'blank') }));
    continue;
  }
  if (lastReply !== null && (lastTouch === null || lastReply >= lastTouch)) {
    stopped.push(Object.assign({}, base, {
      reason: 'they replied — a person takes it from here' }));
    continue;
  }
  if (base.touches_sent >= maxTouches) {
    stopped.push(Object.assign({}, base, {
      reason: 'the sequence is finished (' + base.touches_sent + ' touches)' }));
    continue;
  }

  const next = seq[base.touches_sent];
  if (!next) {
    stopped.push(Object.assign({}, base, { reason: 'no touch left in the sequence' }));
    continue;
  }

  const age = lastTouch === null ? null : (now - lastTouch) / 3600000;
  if (age === null || age >= Number(next.after_hours)) {
    due.push(Object.assign({}, base, {
      touch: next.touch, channel: next.channel, label: next.label,
      quiet_hours: age === null ? null : Math.round(age)
    }));
  } else {
    waiting.push(Object.assign({}, base, {
      reason: 'not due yet — touch ' + next.touch + ' in ' +
        Math.max(0, Math.round(Number(next.after_hours) - age)) + ' h'
    }));
  }
}

return [{
  json: {
    rows_read: rows.length,
    source: source._from || 'the pipeline',
    more_pages: source.more_pages === true,
    total_available: (source.total_available === undefined) ? null : source.total_available,
    due: due,
    waiting: waiting,
    stopped: stopped,
    board: board,
    due_count: due.length,
    _has_due: due.length > 0
  }
}];

// The sequence ran and nothing was due. This node's output is the run report: what is
// waiting, and what has been stopped and why — so a quiet day still says something rather
// than looking like a broken workflow.
const p = $input.first().json || {};
return [{
  json: {
    _outcome: 'nothing due',
    _reason: 'no lead is due a touch today',
    rows_read: p.rows_read,
    due_count: 0,
    waiting: p.waiting || [],
    stopped: p.stopped || [],
    board: p.board || {}
  }
}];

// Writes the words and builds the exact GoHighLevel request for each due touch — one object
// you can read and review. NOTHING is sent from here; this node is pure, and its output is
// what the send node below either sends or shows.
//
// The message is the sequence's own line with a greeting and a signature; GoHighLevel's
// conversations endpoint takes an email as {type, contactId, subject, message} and an SMS as
// {type, contactId, message}. Change the endpoint in one place here if your account differs.
const cfg = $('config').first().json;
const base = String(cfg.ghl_api_base || '').replace(/\/+$/, '');
const seq = cfg.sequence || [];

return $input.all().map((item) => {
  const d = item.json || {};
  const t = seq.filter((s) => s.touch === d.touch)[0] || {};
  const channel = (d.channel || t.channel || 'email').toLowerCase();
  const first = String(d.name || '').split(' ')[0] || 'there';

  const body = 'Hi ' + first + ',\n\n' + (t.line || '') +
    (cfg.from_name ? '\n\n— ' + cfg.from_name : '');
  const subject = t.subject || 'Following up on your enquiry';

  const ghlBody = channel === 'email'
    ? { type: 'Email', contactId: d.contact_id, subject: subject,
        message: '<p>' + body.split('\n\n').join('</p><p>').split('\n').join('<br>') + '</p>' }
    : { type: 'SMS', contactId: d.contact_id, message: body };

  return {
    json: Object.assign({}, d, {
      channel: channel,
      subject: channel === 'email' ? subject : '',
      body: body,
      _ghl: { method: 'POST', url: base + '/conversations/messages', body: ghlBody },
      _would_send: ghlBody
    })
  };
});

// GoHighLevel is not configured (DRY_RUN is still true, or the location id / API key is
// blank). Nothing was sent — and this node's output IS the result: each lead's touch number,
// channel, recipient and the exact words that would have gone out. Open it to read them.
return $input.all().map((i) => ({
  json: {
    _outcome: 'preview — not sent',
    _reason: 'GoHighLevel not configured — nothing was sent',
    contact_key: i.json.contact_key,
    touch: i.json.touch,
    channel: i.json.channel,
    to: i.json.email || i.json.phone || i.json.contact_id,
    subject: i.json.subject,
    body: i.json.body
  }
}));

// The touch reached GoHighLevel. This node's output is the confirmation: whatever the
// conversations endpoint returned for the message it queued.
return $input.all().map((i) => ({
  json: {
    _outcome: 'sent',
    _reason: 'the touch was queued through GoHighLevel',
    ghl_response: i.json
  }
}));

// GoHighLevel refused the touch. Its own node, so a send that failed is a visible step with
// the response on it rather than a run that half-succeeded and said nothing. Read
// `ghl_response` for what it said.
return $input.all().map((i) => {
  const j = i.json || {};
  const err = j.error || j;
  const detail = (err && (err.message || err.description || err.error)) || j;
  return {
    json: {
      _outcome: 'send failed',
      _reason: 'GoHighLevel rejected the touch — nothing was sent for this lead',
      ghl_response: typeof detail === 'string' ? detail : JSON.stringify(detail).slice(0, 600)
    }
  };
});
